test_that("validation-gain helpers reject non-finite weights", {
  toy_data <- data.frame(
    rank = c(10, 20, 30, 40, 50, 60),
    outcome = c(1, 0, 1, 0, 1, 1),
    income = c(2, 4, 6, 8, 10, 12)
  )
  fit <- ci_tree(
    cbind(rank, outcome) ~ income,
    data = toy_data,
    rank_name = "rank",
    outcome_name = "outcome",
    control = ci_tree_control(minsplit = 1, minbucket = 1, maxdepth = 1)
  )

  for (bad_weights in list(
    c(1, Inf, 1, 1, 1, 1),
    c(1, NaN, 1, 1, 1, 1),
    c(1, -Inf, 1, 1, 1, 1)
  )) {
    expect_error(
      ci_tree_validation_gain(
        fit,
        toy_data,
        "rank",
        "outcome",
        weights = bad_weights
      ),
      "finite"
    )
  }
})

test_that("relative validation gain scales validation gain by root impurity", {
  toy_data <- data.frame(
    rank = c(10, 20, 30, 40, 50, 60),
    outcome = c(1, 0, 1, 0, 1, 1),
    income = c(2, 4, 6, 8, 10, 12)
  )
  fit <- ci_tree(
    cbind(rank, outcome) ~ income,
    data = toy_data,
    rank_name = "rank",
    outcome_name = "outcome",
    control = ci_tree_control(minsplit = 1, minbucket = 1, maxdepth = 1)
  )
  weights <- rep(1, nrow(toy_data))
  y <- as.matrix(toy_data[c("rank", "outcome")])
  root_impurity <- ci_factory("CI")(y, weights)
  validation_gain <- ci_tree_validation_gain(
    fit, toy_data, "rank", "outcome",
    weights = weights,
    type = "CI",
    root_impurity = root_impurity
  )
  relative_gain <- getFromNamespace(
    ".ci_score_relative_validation_gain",
    "ineqTrees"
  )(
    fit = fit,
    new_data = toy_data,
    rank_name = "rank",
    outcome_name = "outcome",
    weights = weights,
    type = "CI",
    root_impurity = root_impurity
  )

  expect_equal(relative_gain, validation_gain / abs(root_impurity))
})

test_that("ci_forest_validation_gain averages internal tree gains", {
  toy_data <- data.frame(
    rank = c(10, 20, 30, 40, 50, 60, 70, 80),
    outcome = c(1, 0, 1, 0, 1, 1, 0, 1),
    income = c(2, 4, 6, 8, 10, 12, 14, 16),
    group = factor(c("a", "a", "b", "b", "a", "a", "b", "b"))
  )
  set.seed(11)
  forest <- ci_forest(
    cbind(rank, outcome) ~ income + group,
    data = toy_data,
    rank_name = "rank",
    outcome_name = "outcome",
    ntree = 4L,
    mtry = 1L,
    control = ci_tree_control(minsplit = 1, minbucket = 1, maxdepth = 1)
  )
  weights <- rep(1, nrow(toy_data))
  root_impurity <- ci_root_impurity(
    toy_data,
    rank_name = "rank",
    outcome_name = "outcome",
    weights = weights,
    type = "CI"
  )

  score <- ci_forest_validation_gain(
    forest,
    toy_data,
    rank_name = "rank",
    outcome_name = "outcome",
    weights = weights,
    type = "CI",
    root_impurity = root_impurity
  )
  manual <- mean(vapply(
    forest$trees,
    function(tree) {
      ci_tree_validation_gain(
        tree$fit,
        toy_data,
        rank_name = "rank",
        outcome_name = "outcome",
        weights = weights,
        type = "CI",
        root_impurity = root_impurity
      )
    },
    numeric(1)
  ))

  expect_equal(score, manual)
})

test_that("ci prediction metrics score simple binary predictions", {
  truth <- c(0, 1, 1, 0)
  estimate <- c(0.1, 0.8, 0.7, 0.2)

  expect_lt(ci_brier_score(truth, estimate), 0.1)
  expect_lt(ci_log_loss(truth, estimate), 0.4)
  expect_equal(ci_roc_auc(truth, estimate), 1)

  out <- ci_prediction_metrics(truth, estimate)
  expect_s3_class(out, "data.table")
  expect_true(all(c("brier", "log_loss", "roc_auc") %in% names(out)))
})

test_that("ci_log_loss rejects infinite predictions before clipping", {
  expect_error(
    ci_log_loss(c(0, 1), c(-Inf, Inf)),
    "must contain only finite values"
  )
  expect_error(
    ci_log_loss(c(0, 1), c(0.5, Inf)),
    "must contain only finite values"
  )
  expect_error(
    ci_log_loss(c(0, Inf), c(0.4, 0.6)),
    "`truth` must not contain infinite"
  )
})

test_that("ci_log_loss validates eps and binary truth", {
  expect_error(
    ci_log_loss(c(0, 1), c(0.4, 0.6), eps = 0),
    "strictly between 0 and 0.5"
  )
  expect_error(
    ci_log_loss(c(0, 1), c(0.4, 0.6), eps = 0.5),
    "strictly between 0 and 0.5"
  )
  expect_error(
    ci_log_loss(c(0, 1), c(0.4, 0.6), eps = Inf),
    "strictly between 0 and 0.5"
  )
  expect_error(
    ci_log_loss(c(0, 0.3, 1), c(0.2, 0.3, 0.9)),
    "requires a binary outcome"
  )
})

test_that("ci_log_loss keeps valid boundary probabilities finite", {
  loss <- ci_log_loss(c(0, 1, 1, 0), c(0, 1, 0, 1), eps = 1e-9)

  expect_true(is.finite(loss))
  expect_gt(loss, 0)
  expect_equal(
    loss,
    mean(-(c(0, 1, 1, 0) * log(pmax(pmin(c(0, 1, 0, 1), 1 - 1e-9), 1e-9)) +
      (1 - c(0, 1, 1, 0)) * log(1 - pmax(pmin(c(0, 1, 0, 1), 1 - 1e-9), 1e-9))))
  )
})

test_that("ci_log_loss still matches an independent hand calculation", {
  truth <- c(0, 1, 1, 0)
  estimate <- c(0.1, 0.8, 0.7, 0.2)
  weights <- c(1, 2, 1, 2)

  expected <- stats::weighted.mean(
    -(truth * log(estimate) + (1 - truth) * log(1 - estimate)),
    weights
  )

  expect_equal(ci_log_loss(truth, estimate, weights), expected)
})

test_that("ci_brier_score and ci_roc_auc reject infinite predictions", {
  expect_error(
    ci_brier_score(c(0, 1), c(0.2, Inf)),
    "must contain only finite values"
  )
  expect_error(
    ci_roc_auc(c(0, 1), c(0.2, Inf)),
    "must contain only finite values"
  )
  expect_error(
    ci_roc_auc(c(0, 1), c(0.2, 0.8)),
    NA
  )
})
